"""Provenance and lineage helper functions for resilience predictions and models."""

from __future__ import annotations

import re
from typing import Any, Dict, List, Optional, Union

from urban_resilience.types import PredictionProvenance

SHA256_HEX_REGEX = re.compile(r"^[0-9a-fA-F]{64}$")


def is_synthetic_trained(prov: Optional[Union[PredictionProvenance, Dict[str, Any]]]) -> bool:
    """Returns True if prediction was generated by a model trained on synthetic simulator data."""
    if prov is None:
        return False
    if isinstance(prov, PredictionProvenance):
        is_trained = (prov.summary_metric_source == "trained_model" or prov.model_status == "trained_model")
        return is_trained and prov.training_label_source == "synthetic_simulator" and prov.engineering_only is True
    if isinstance(prov, dict):
        is_trained = (prov.get("summary_metric_source") == "trained_model" or prov.get("model_status") == "trained_model")
        return is_trained and prov.get("training_label_source") == "synthetic_simulator" and bool(prov.get("engineering_only")) is True
    return False


def is_untrained_fallback(prov: Optional[Union[PredictionProvenance, Dict[str, Any]]]) -> bool:
    """Returns True if prediction used Monte Carlo physics fallback rather than a trained model."""
    if prov is None:
        return True
    if isinstance(prov, PredictionProvenance):
        return prov.model_status == "untrained_fallback" or prov.summary_metric_source == "monte_carlo_physics"
    if isinstance(prov, dict):
        return prov.get("model_status") == "untrained_fallback" or prov.get("summary_metric_source") == "monte_carlo_physics"
    return False


def build_provenance_warnings(prov: Optional[Union[PredictionProvenance, Dict[str, Any]]]) -> List[str]:
    """Generates appropriate lineage and provenance warnings for the prediction.

    - synthetic trained: Warning that model artifact was trained on synthetic simulator labels.
    - trained but unverified / untagged label source: Warning that training provenance is unknown/missing.
    - untrained fallback: No synthetic artifact warnings.
    """
    if prov is None:
        return []

    if isinstance(prov, PredictionProvenance):
        is_trained = (prov.summary_metric_source == "trained_model" or prov.model_status == "trained_model")
        label_source = prov.training_label_source
        eng_only = prov.engineering_only
        prov_status = getattr(prov, "provenance_status", None)
    elif isinstance(prov, dict):
        is_trained = (prov.get("summary_metric_source") == "trained_model" or prov.get("model_status") == "trained_model")
        label_source = prov.get("training_label_source")
        eng_only = prov.get("engineering_only")
        prov_status = prov.get("provenance_status")
    else:
        return []

    warnings: List[str] = []

    if is_trained:
        if label_source == "synthetic_simulator" and eng_only is True:
            warnings.append(
                "Model artifact trained on synthetic simulator labels (engineering_only=True). "
                "Not an empirical disaster benchmark."
            )
        elif label_source in ("unknown", None, "none", "") or prov_status == "unverified":
            warnings.append(
                "Model artifact has no verified training provenance (training_label_source is unverified or missing)."
            )

    return warnings


def get_synthetic_warning(prov: Optional[Union[PredictionProvenance, Dict[str, Any]]]) -> Optional[str]:
    """Returns synthetic simulator warning string if model is synthetic trained, else None."""
    if is_synthetic_trained(prov):
        return (
            "Model artifact trained on synthetic simulator labels (engineering_only=True). "
            "Not an empirical disaster benchmark."
        )
    return None


def get_provenance_warning(prov: Optional[Union[PredictionProvenance, Dict[str, Any]]]) -> Optional[str]:
    """Returns primary provenance warning string if any, else None."""
    warnings = build_provenance_warnings(prov)
    return warnings[0] if warnings else None


def validate_verified_data_provenance(p: Any) -> None:
    """Validates that a verified data provenance record satisfies empirical audit criteria.

    Args:
        p: Candidate provenance dictionary.

    Raises:
        ValueError: If record is missing, not a dict, or fails any empirical audit requirement.
    """
    if not isinstance(p, dict) or not p:
        raise ValueError(f"verified_data_provenance must be a non-empty dictionary, got {type(p).__name__}")

    if p.get("data_kind") != "observed":
        raise ValueError(
            f"Invalid data_kind '{p.get('data_kind')}'. Verified real provenance must have data_kind='observed'."
        )

    if p.get("provenance_status") != "verified":
        raise ValueError(
            f"Invalid provenance_status '{p.get('provenance_status')}'. Must be 'verified'."
        )

    for field_name in ("event_id", "source", "license"):
        val = p.get(field_name)
        if not isinstance(val, str) or not val.strip():
            raise ValueError(
                f"Field '{field_name}' in verified_data_provenance must be a non-empty string."
            )

    data_hash = p.get("data_hash")
    if not isinstance(data_hash, str) or not SHA256_HEX_REGEX.match(data_hash):
        raise ValueError(
            f"Field 'data_hash' must be a 64-character hexadecimal SHA-256 checksum string, got '{data_hash}'."
        )
